with FilteredOrders as (select * from orders where amount between 470 and 940 and (status = 'CANCELLED' or store_id is not null)), Summary as (select date_trunc('MONTH', order_date) as order_month, round(avg(discount), 2) as avg_discount from FilteredOrders group by date_trunc('MONTH', order_date)) select order_month, avg_discount from Summary order by avg_discount desc, order_month;
